LINK = re.compile(r"\[\[([^\]|]+)(?:\|([^\]]+))?\]\]")
def plain(e):
    return LINK.sub(lambda m: m.group(2) or m.group(1), e).replace("*", "")
def sortkey(h):
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9]+", " ", h.lower())).strip()
out = []
for key, head, lvl, body in ENT:
    out.append({"key": key, "headword": head, "sort_key": sortkey(head), "entry": body})
    n = len(plain(body).split())
    nl = len(LINK.findall(body))
    flag = ""
    if lvl == 4 and not (100 <= n <= 150): flag = " <-- L4 range"
    if lvl == 5 and n > 100: flag = " <-- L5 over 100"
    if nl > 8: flag += " <-- LINKS"
    print(f"{n:4d} L{lvl} links={nl} {head}{flag}")
if "--write" in sys.argv:
    with open("/home/user/concise-encyclopedia/data/condensed/haiku_471.json", "w", encoding="utf-8") as f:
        f.write("[\n" + ",\n".join(json.dumps(o, ensure_ascii=False) for o in out) + "\n]\n")
    print("written", len(out))
